(() => {
  const root=document.getElementById('iwr-night-conditional');
  const canvas=root.querySelector('canvas'),ctx=canvas.getContext('2d');
  const pause=root.querySelector('[data-pause]'),caption=root.querySelector('[data-description]');
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const state={style:'confidence',mode:'play',paused:reduced.matches,accent:true};
  const names={confidence:'Confidence Fence',closure:'Vector Closure',escapement:'Cycle Escapement',detour:'Reversible Detour',mutation:'Mutation Quota'};
  const descriptions={
    confidence:['Tahmin ile kayıt karşılaşıyor; uyuşmazlık dar aralığı yeniden açıyor.','Son üç örnek yakınsadıkça köşeler daralıyor; aykırı örnek aralığı genişletiyor.'],
    closure:['İki güçlü hareket birbirini silebiliyor; üçüncü kenar her zaman tam toplamı kapatıyor.','İlk yön tutuluyor, ikinci ekleniyor; ancak ikisi tamamlanınca kapanış çiziliyor.'],
    escapement:['Küçük sayaç her vuruşta ilerliyor; büyük iz yalnız dördüncü vuruşta yer değiştiriyor.','Üç girişten yalnız biri yeni bir çıkış yazıyor; diğer girişler küçük sayacı ilerletiyor.'],
    detour:['Sağdaki geçici değişimler siliniyor; şekil soldaki özgün kayda eksiksiz dönüyor.','Değişiklikler sağda birikiyor; bırakınca tümü atılıyor, ilk kayıt aynen geri geliyor.'],
    mutation:['Aynı yedi parça tekrar tekrar okunuyor; üç turda yalnız bir parça değişebiliyor.','Bir değişiklik hakkı geliyor; tur bitince tek parçaya harcanıyor, diğer altısı korunuyor.']
  };
  const white='#f1f0e8',amber='#FF0000';
  let w=226,dpr=1,t=2.4,last=0,raf=0,visible=true;
  const clamp=(x,a=0,b=1)=>Math.min(b,Math.max(a,x));
  // Live sound seam: iwrSignal exists only inside the archive gallery. Without it, or with sound off, nothing changes.
  const hearing=()=>typeof iwrSignal!=='undefined'&&iwrSignal.active?iwrSignal:null;
  // Geometry reads audio features. Transport and history have separate clocks.
  const charge=(band='amp',age=0)=>{const s=hearing();return s?clamp(s.bandAt?s.bandAt(band,age):(s[band]??s.level??0)):0;};
  const strike=(kind='kick')=>{const s=hearing();return s?.eventAt?s.eventAt(kind):{n:Math.floor(s?.beat??0),age:s?.[kind+'Age']??30};};
  // Time-driven machines move on the beat and rest between hits; the studies' own dt clamps still apply first.
  const conduct=()=>{const s=hearing();return s?0.25+4.2*s.hit:1;};
  const mod=(x,n)=>(x%n+n)%n;
  const accent=()=>state.accent?amber:white;
  function ink(alpha=1,color=white){ctx.globalAlpha=clamp(alpha);ctx.fillStyle=color;ctx.strokeStyle=color;}
  function rect(x,y,width,height,alpha=1,color=white){ink(alpha,color);ctx.fillRect(Math.round(x*dpr)/dpr,Math.round(y*dpr)/dpr,width,height);}
  function line(points,alpha=1,color=white){if(points.length<2)return;ink(alpha,color);ctx.lineWidth=1;ctx.lineCap='butt';ctx.lineJoin='miter';ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();}
  // Synthetic observations and schedules only. No audio analysis or device access.
  const observations=[-.45,.3,-.12,.07,.1,.08,.58,.13,.11,.1,-.35,.08];
  function confidenceState(time,recording){
    if(hearing()){const e=strike('note'),previous=[.18,.36,.54].map(age=>charge('mid',age)-.5),prediction=previous.reduce((a,b)=>a+b,0)/3,actual=charge('mid')-.5,candidates=[prediction,actual],center=(prediction+actual)/2;return {event:e.n,age:e.age,center,radius:Math.max(.075,Math.abs(actual-prediction)/2+.04),candidates,prediction,actual,revealed:true};}
    const phase=mod(time,9.6),event=Math.min(11,Math.floor((phase+1e-10)/.8)),age=Math.max(0,phase-event*.8);
    const previous=[2,1,0].map(offset=>observations[mod(event-1-offset,12)]),prediction=previous.reduce((a,b)=>a+b,0)/3;
    const actual=observations[event],revealed=recording||age>=.2;
    const candidates=recording?[2,1,0].map(offset=>observations[mod(event-offset,12)]):(revealed?[prediction,actual]:[prediction]);
    const center=candidates.reduce((a,b)=>a+b,0)/candidates.length;
    const radius=Math.max(.075,...candidates.map(value=>Math.abs(value-center)+.04));
    return {event,age,center,radius,candidates,prediction,actual,revealed};
  }
  function confidence(time){
    const recording=state.mode==='record',s=confidenceState(time,recording),map=value=>w/2+value*(w-26)/1.5;
    const l=map(s.center-s.radius),r=map(s.center+s.radius),c=map(s.center);
    line([[l+5,10],[l,10],[l,16]],.75);line([[l,28],[l,34],[l+5,34]],.75);
    line([[r-5,10],[r,10],[r,16]],.75);line([[r,28],[r,34],[r-5,34]],.75);
    line([[c-2,20],[c+2,24]],1);
    s.candidates.forEach((value,i)=>{const x=map(value),y=recording?16+i*6:(i?28:16);line([[x,y-3],[x,y+3]],.9,i===s.candidates.length-1&&s.age<.36?accent():white);});
    if(!recording&&s.revealed&&Math.abs(s.actual-s.prediction)>.2&&s.age<.36)line([[map(s.prediction),37],[map(s.actual),37]],1,accent());
  }
  function closureState(time,recording){
    const phase=mod(time,3.6),stage=Math.min(2,Math.floor((phase+1e-10)/1.2));
    const sample=recording?Math.floor(time/3.6)*.91:time*.65;
    const a=hearing()?[w*(.26+.16*charge('low')),(charge('mid')-.5)*22]:[w*(.34+.08*Math.sin(sample*.7)),11*Math.sin(sample)],sum=hearing()?[w*.14*(charge('high')-charge('low')),(charge('amp')-.5)*24]:[w*.14*Math.sin(sample*1.7),12*Math.sin(sample*.8)];
    const b=[sum[0]-a[0],sum[1]-a[1]],origin=[w*.24,22];
    return {a,b,sum,origin,stage};
  }
  function closure(time){
    const recording=state.mode==='record',{a,b,sum,origin:o,stage}=closureState(time,recording);
    const p=[o[0]+a[0],o[1]+a[1]],q=[p[0]+b[0],p[1]+b[1]];
    line([[o[0]-3,o[1]-3],[o[0]-3,o[1]+3],[o[0]+2,o[1]+3]],.45);
    line([o,p],.65);line([[p[0]-2,p[1]-2],[p[0]+2,p[1]+2]],.9);
    if(!recording||stage>=1){line([p,q],1);line([[q[0]-2,q[1]+2],[q[0]+2,q[1]-2]],1);}
    if(!recording||stage>=2){line([q,o],.9,accent());if(Math.hypot(...sum)<3)rect(o[0]-1,o[1]-1,2,2,1,accent());}
  }
  function escapementState(time,n){if(hearing()){const e=strike('kick');return {beat:e.n,remainder:mod(e.n,n),carry:Math.floor(e.n/n),age:e.age};}const beat=Math.floor((time+1e-10)/.52);return {beat,remainder:beat%n,carry:Math.floor(beat/n),age:Math.max(0,time-beat*.52)};}
  function escapement(time){
    const recording=state.mode==='record',n=recording?3:4,s=escapementState(time,n),pitch=7;
    for(let i=0;i<n;i++){const x=7+i*7,y=12+i*5;line([[x,y],[x+5,y],[x+5,y+3]],.35);}
    const mx=7+s.remainder*7,my=12+s.remainder*5;
    line([[mx-2,my-3],[mx+5,my-3]],1,s.age<.16?accent():white);
    const left=46,span=w-left-10,output=mod(s.carry,5),x=left+span*(output+.5)/5;
    line([[x,10],[x,34]],1);line([[x-5,10],[x,10],[x,15]],.85);line([[x,29],[x,34],[x+5,34]],.85);
    if(s.remainder===0&&s.age<.18){line([[x-4,38],[x+4,38]],1,accent());if(recording)rect(x-1,5,2,2,1,accent());}
  }
  const references=[[-2,-10,7,-4,3],[5,-5,-9,8,-2],[-7,6,10,-6,2]];
  const edits=[[0,5,-4,0,0],[0,0,5,-7,0],[0,-4,0,5,0]];
  function detourState(time,recording){
    if(hearing()){const e=strike('snare'),reference=references[mod(e.n,3)].slice(),active=e.age<.5,current=reference.map((v,i)=>v+(active?(charge(['low','mid','high','mid','low'][i])-.5)*10:0));return {cycle:e.n,phase:e.age,reference,current,active,restored:!active};}
    const cycle=Math.floor((time+1e-10)/4.8),phase=Math.max(0,time-cycle*4.8),reference=references[mod(cycle,3)].slice();
    const active=phase>=.8&&phase<3.2,change=active?Math.min(3,Math.floor((phase+1e-10)/.8)):0;
    const current=reference.slice();
    for(let e=0;e<change;e++)for(let j=0;j<5;j++)current[j]+=edits[e][j];
    if(active&&!recording){const amount=2*Math.sin((phase-.8)*Math.PI/.8);current[2]+=amount;current[3]-=amount;}
    return {cycle,phase,reference,current,active,restored:phase>=3.2};
  }
  function detour(time){
    const s=detourState(time,state.mode==='record'),width=(w-34)/2,xs=[0,.17,.43,.78,1];
    const points=(values,offset)=>values.map((value,i)=>[offset+xs[i]*width,22+value]);
    line(points(s.reference,6),.6);line(points(s.current,w/2+11),1);
    if(s.active){line([[w/2+11,38],[w/2+11+width,38]],.65,accent());}
    else if(s.restored&&s.phase<3.4){line([[w/2-3,18],[w/2-3,26]],1,accent());}
  }
  const mutationSeed=[0,1,2,0,2,1,0];
  function mutationState(time,recording){
    if(hearing()){const e=strike('hat'),values=mutationSeed.map((v,i)=>mod(v+Math.floor(charge(['low','mid','high'][i%3],i*.08)*3),3));return {values,pass:e.n,age:e.age,period:.28,changed:mod(e.n,7),pending:false,reader:clamp(e.age/.2),editsDone:e.n};}
    const period=recording?1.4:1.12,cycle=period*63,phase=mod(time,cycle),pass=Math.min(62,Math.floor((phase+1e-10)/period)),age=Math.max(0,phase-pass*period),editsDone=Math.floor(pass/3);
    const values=mutationSeed.slice();for(let e=0;e<editsDone;e++){const slot=e*3%7;values[slot]=(values[slot]+1)%3;}
    const changed=pass%3===0?mod((editsDone-1)*3,7):-1,pending=pass%3===2&&age>=period*.65;
    return {values,pass,age,period,changed,pending,reader:clamp(age/period),editsDone};
  }
  function mutation(time){
    const recording=state.mode==='record',s=mutationState(time,recording),pitch=(w-20)/7;
    s.values.forEach((value,i)=>{
      const x=10+(i+.5)*pitch,half=3+(i%3),dx=value===0?-3:value===1?3:0;
      line([[x-dx,22-half],[x+dx,22+half]],.95);
      if(i===s.changed&&s.age<.2)line([[x-4,33],[x+4,33]],1,accent());
    });
    const x=10+s.reader*(w-20);line([[x,8],[x,13]],.9);
    if(recording&&s.pending)line([[w-11,4],[w-5,4]],1,accent());
  }
  const renderers={confidence,closure,escapement,detour,mutation};
  function draw(){ctx.clearRect(0,0,w,44);ctx.save();ctx.beginPath();ctx.rect(0,0,w,44);ctx.clip();renderers[state.style](t);ctx.restore();}
  function sync(){
    root.querySelectorAll('[data-style]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.style===state.style)));
    root.querySelectorAll('[data-mode]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.mode===state.mode)));
    const description=descriptions[state.style][state.mode==='record'?1:0];caption.textContent=description;canvas.setAttribute('aria-label',names[state.style]+': '+description);
    root.querySelector('[data-record]').hidden=state.mode!=='record';pause.textContent=state.paused?'Devam et':'Duraklat';pause.setAttribute('aria-pressed',String(state.paused));draw();schedule();
  }
  function resize(){w=Math.max(1,canvas.getBoundingClientRect().width);dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=44*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw();}
  function schedule(){if(!raf&&!state.paused&&visible&&!document.hidden&&root.isConnected){last=0;raf=requestAnimationFrame(frame);}}
  function frame(now){raf=0;if(state.paused||!visible||document.hidden||!root.isConnected)return;if(!last)last=now;const elapsed=now-last;if(elapsed>=1000/30){const heard=hearing();if(heard?.source==='demo')t=heard.songTime;else t+=Math.min(elapsed/1000,.07)*conduct();last=now;draw();}raf=requestAnimationFrame(frame);}
  root.querySelectorAll('[data-style]').forEach(el=>el.addEventListener('click',()=>{state.style=el.dataset.style;sync();}));
  root.querySelectorAll('[data-mode]').forEach(el=>el.addEventListener('click',()=>{state.mode=el.dataset.mode;sync();}));
  pause.addEventListener('click',()=>{state.paused=!state.paused;sync();});reduced.addEventListener('change',()=>{state.paused=reduced.matches;sync();});
  document.addEventListener('visibilitychange',schedule);new ResizeObserver(resize).observe(canvas);
  new IntersectionObserver(entries=>{const latest=entries.reduce((a,b)=>b.target===root&&(!a||b.time>=a.time)?b:a,null);if(latest){visible=latest.isIntersecting;schedule();}}).observe(root);
  resize();sync();
  if(globalThis.Tweak){const tweak=new Tweak({container:root.querySelector('.nc-phone'),onChange:sync});tweak.addToggle(state,'accent',{label:'Kehribar vurgu'});}
})();
